        fresh.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        Claim claim = claims.saveAndFlush(fresh);
        keepTags(claim);
        logStatus(user, person, claim);
        record("CLAIM_ADDED", user, person, claim, claim.getNumber(),
